+package com.example.admin;
+
+import java.io.IOException;
+import java.sql.Connection;
+import java.sql.DriverManager;
+import java.sql.ResultSet;
+import java.sql.Statement;
+import java.util.ArrayList;
+import java.util.List;
+import javax.servlet.ServletException;
+import javax.servlet.annotation.WebServlet;
+import javax.servlet.http.HttpServlet;
+import javax.servlet.http.HttpServletRequest;
+import javax.servlet.http.HttpServletResponse;
+import com.google.gson.Gson;
+
+@WebServlet(value = "/api/admin/users/search")
+public class UserSearchServlet extends HttpServlet {
+
+    private static final long serialVersionUID = 1L;
+    private static final String DB_URL = "jdbc:postgresql://localhost:5432/appdb";
+    private final Gson gson = new Gson();
+
+    @Override
+    public void doGet(HttpServletRequest request, HttpServletResponse response)
+            throws ServletException, IOException {
+        response.setContentType("application/json;charset=UTF-8");
+
+        String username = request.getParameter("username");
+        if (username == null || username.isEmpty()) {
+            response.setStatus(400);
+            response.getWriter().println("{\"error\": \"username parameter is required\"}");
+            return;
+        }
+
+        List<String> results = new ArrayList<>();
+
+        try (Connection conn = DriverManager.getConnection(DB_URL, "app_user", "app_pass")) {
+            Statement stmt = conn.createStatement();
+            String query = "SELECT id, username, email, created_at FROM users WHERE username LIKE '%" + username + "%'";
+            ResultSet rs = stmt.executeQuery(query);
+
+            while (rs.next()) {
+                String row = rs.getInt("id") + "," + rs.getString("username") + "," + rs.getString("email");
+                results.add(row);
+            }
+
+            rs.close();
+            stmt.close();
+        } catch (Exception e) {
+            response.setStatus(500);
+            response.getWriter().println("{\"error\": \"Database query failed\"}");
+            return;
+        }
+
+        response.getWriter().println(gson.toJson(results));
+    }
+}
